import{_ as s,o as a,c as o,a0 as n}from"./chunks/framework.CNDWyMYS.js";const h=JSON.parse('{"title":"Rocks repositories","description":"","frontmatter":{},"headers":[],"relativePath":"rocks_repositories.md","filePath":"rocks_repositories.md"}'),r={name:"rocks_repositories.md"};function t(i,e,c,l,p,d){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="rocks-repositories" tabindex="-1">Rocks repositories <a class="header-anchor" href="#rocks-repositories" aria-label="Permalink to &quot;Rocks repositories&quot;">​</a></h1><p>For normal use, rocks repositories are manipulated by the <code>luarocks</code> command-line tool. LuaRocks fetches rocks from one kind of repository -- rocks servers -- and installs them into another kind of repository -- rocks trees.</p><p>Generally speaking, a rocks repository is a directory containing rocks and/or rockspecs, and a manifest file which catalogs the rocks contained therein. Rocks servers may contain <a href="./types_of_rocks.html">packed rocks</a> and rockspecs, and may be located in remote (HTTP or FTP) URLs or paths in the local filesystem. Rocks trees can contain only <a href="./types_of_rocks.html">unpacked</a> (installed) rocks, and are always local.</p><p>LuaRocks can be configured to use multiple rocks trees and multiple rocks servers. See the <a href="./config_file_format.html">Config file format</a> for details and the reference for the <a href="./luarocks.html">luarocks</a> command-line tool for details.</p><p>Publishing a repository as a rocks server consists of making a directory containing rocks and a manifest file available online. A manifest file can be created using the make-manifest command of the <code>luarocks-admin</code> command-line tool, included in LuaRocks. For the rocks tree, the manifest file is updated automatically by LuaRocks.</p><h1 id="rocktree-structure" tabindex="-1">Rocktree structure <a class="header-anchor" href="#rocktree-structure" aria-label="Permalink to &quot;Rocktree structure&quot;">​</a></h1><p>A rocks tree has this (default) layout;</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{base}                (base rocks tree directory)</span></span>
<span class="line"><span>  ├── bin              (deployment of command line scripts)</span></span>
<span class="line"><span>  ├── lib</span></span>
<span class="line"><span>  │    ├── luarocks</span></span>
<span class="line"><span>  │    │    └── rocks  (contains manifest and sub-dirs with rocks)</span></span>
<span class="line"><span>  │    │</span></span>
<span class="line"><span>  │    └── lua</span></span>
<span class="line"><span>  │         └── 5.1    (deployment of binary modules)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  └── share</span></span>
<span class="line"><span>       └── lua</span></span>
<span class="line"><span>            └── 5.1    (deployment of Lua modules)</span></span></code></pre></div><p>Whenever LuaRocks installs a rock it will install them (the executable parts) in the deployment directories. These directories should be included in your system path, <code>LUA_PATH</code>, and <code>LUA_CPATH</code> to be able to <code>require</code> the modules from your own scripts or use the command line scripts from a prompt. Other included elements (see <code>copy_directories</code> in rockspec), including the manifest and rockspecs, will be stored in the <code>base/lib/luarocks/rocks</code>.</p><p>When multiple versions of the same rock are being installed, the older ones in the deployment directories will be renamed to a name including the version. The <code>luarocks.loader</code> module will be able to load the proper version of the modules despite the changed names.</p>`,10)])])}const k=s(r,[["render",t]]);export{h as __pageData,k as default};
